function pelagoT(
    game: GameRuntime,
    key: string,
    fallbackFr: string,
    fallbackEn: string,
    vars: Record<string, string | number> = {},
): string {
    const lang = typeof game.normalizeLanguage === 'function'
        ? game.normalizeLanguage(game.language)
        : 'fr';
    if (typeof game.t === 'function') {
        const out = game.t(key, vars);
        if (out && out !== key) return out;
    }
    const template = lang === 'en' ? fallbackEn : fallbackFr;
    return template.replace(/\{(\w+)\}/g, (_, k: string) => String(vars[k] ?? `{${k}}`));
}

function interpolateProdSourcesTooltip(
    game: GameRuntime,
    ui: PokePelagoUiSnapshot,
    bonusPct: number,
): { prodSourcesTooltipTitle: string; prodSourcesTooltipBody: string } {
    const pelagoPer = Math.round(POKE_PELAGO.prodBonusPerLevel * 100);
    const masteryPer = Math.round(POKE_PELAGO.masteryProdBonusPerLevel * 100);
    const alola = Math.round((POKE_PELAGO.abeensAlolaAffinityMult - 1) * 100);
    return {
        prodSourcesTooltipTitle: pelagoT(
            game,
            'pokePelago.prodSourcesTooltipTitle',
            ui.prodSourcesTooltipTitle,
            ui.prodSourcesTooltipTitle,
        ),
        prodSourcesTooltipBody: pelagoT(
            game,
            'pokePelago.prodSourcesTooltipBody',
            ui.prodSourcesTooltipBody,
            ui.prodSourcesTooltipBody,
            { pct: bonusPct, pelagoPer, masteryPer, alola },
        ),
    };
}

function langOf(game: GameRuntime): 'fr' | 'en' {
    const lang = typeof game.normalizeLanguage === 'function'
        ? game.normalizeLanguage(game.language)
        : 'fr';
    return lang === 'en' ? 'en' : 'fr';
}

function itemLabel(game: GameRuntime, itemKey: string): string {
    const def = (ALL_ITEMS as Record<string, Record<string, unknown>>)[itemKey];
    if (typeof game.getLocalizedItemName === 'function') {
        return game.getLocalizedItemName(itemKey, coerceStr(def?.name, itemKey), def);
    }
    return coerceStr(def?.name, itemKey);
}

function creatureDisplayName(game: GameRuntime, creature: CreatureData): string {
    if (typeof game.getLocalizedPokemonName === 'function') {
        return game.getLocalizedPokemonName(creature.name) || creature.name;
    }
    return String(creature.name || '?');
}

